// Log de la corrida: una línea CSV por factura con todo el contexto (folio, uuid,
// proyecto, modelo, depa, propiedad, cuenta, descripción, qué se cargó y por qué no).
const pares = $('Emparejar por folio').all().map((i) => i.json);
const plan = $('Planear cargas').all().map((i) => i.json);

const leer = (nodo) => {
  try { return $(nodo).all().map((i) => i.json); } catch (e) { return []; }
};
const insertados = leer('Insertar documento');
const urls = leer('Construir URL pública');

const cfg = $('Configuración').first().json;
const TIPO_XML = cfg.id_tipo_documento_xml || 21;
const TIPO_PDF = cfg.id_tipo_documento_pdf || 22;

// Inserciones que de verdad quedaron (la fila devuelta trae id).
const insertadoPor = new Set();
for (const r of insertados) {
  if (r && r.id && r.id_cuenta_cobranza) insertadoPor.add(r.id_cuenta_cobranza + ':' + r.id_tipo_documento);
}
// URL final por cuenta+tipo.
const urlPor = new Map();
for (const u of urls) {
  if (u && u.id_cuenta_cobranza) urlPor.set(u.id_cuenta_cobranza + ':' + u.id_tipo_documento, u.url_publica);
}

const RAZONES = {
  ya_tenia_ambos: 'Ya tenia XML y PDF activos en la cuenta',
  sin_cuenta_de_cobranza: 'No se encontro cuenta de cobranza para ese depa',
  no_se_pudo_parsear_descripcion: 'No se pudo leer el depa en la descripcion del CFDI',
  proyecto_sin_id_producto_mapeado: 'El proyecto no tiene id_producto en la configuracion',
  falta_documento_pero_no_hay_archivo_en_drive: 'Falta el documento pero no esta el archivo en Drive',
  fallo_insert_xml: 'Fallo el insert del XML',
  fallo_insert_pdf: 'Fallo el insert del PDF'
};
const explicar = (m) => {
  if (!m) return '';
  if (RAZONES[m]) return RAZONES[m];
  if (m.startsWith('cuenta_ambigua_')) return 'Varias cuentas activas para ese depa (' + m.replace('cuenta_ambigua_', '').replace('_coincidencias', '') + '); no se carga por seguridad';
  return m;
};

// Una fila por factura (folio del Drive).
const porFolio = new Map();
for (const p of plan) {
  const clave = p.folio || ('cuenta_' + p.id_cuenta_cobranza);
  if (!porFolio.has(clave)) {
    porFolio.set(clave, {
      folio: p.folio || '',
      uuid: p.uuid || '',
      proyecto: p.proyecto || '',
      modelo: p.modelo || '',
      num_depa: p.num_depa || '',
      numero_propiedad: p.numero_propiedad || '',
      id_propiedad: p.id_propiedad || '',
      id_cuenta_cobranza: p.id_cuenta_cobranza || '',
      descripcion: p.descripcion || '',
      xml_name: p.xml_name || '',
      pdf_name: p.pdf_name || '',
      tenia_xml: p.tiene_xml === true,
      tenia_pdf: p.tiene_pdf === true,
      inferido: p.proyecto_inferido_por_modelo === true,
      cargo_xml: false,
      cargo_pdf: false,
      motivos: new Set()
    });
  }
  const g = porFolio.get(clave);
  if (p.motivo) g.motivos.add(p.motivo);
  if (p.accion === 'subir' && p.id_cuenta_cobranza) {
    const ok = insertadoPor.has(p.id_cuenta_cobranza + ':' + p.id_tipo_documento);
    if (p.tipo === 'xml') g.cargo_xml = g.cargo_xml || ok;
    if (p.tipo === 'pdf') g.cargo_pdf = g.cargo_pdf || ok;
    if (!ok) g.motivos.add('fallo_insert_' + p.tipo);
  }
}

const filas = [...porFolio.values()].sort((a, b) => String(a.folio).localeCompare(String(b.folio)));
const si = (b) => (b ? 'si' : 'no');
const csv = (v) => '"' + String(v === null || v === undefined ? '' : v).split('"').join('""') + '"';
const urlDe = (f, tipo) => urlPor.get(f.id_cuenta_cobranza + ':' + (tipo === 'xml' ? TIPO_XML : TIPO_PDF)) || '';

const totalArchivos = pares.reduce((n, p) => n + (p.xml_file_id ? 1 : 0) + (p.pdf_file_id ? 1 : 0), 0);
const conCuenta = filas.filter((f) => f.id_cuenta_cobranza).length;
const insXml = insertados.filter((r) => r && r.id && r.id_tipo_documento === TIPO_XML).length;
const insPdf = insertados.filter((r) => r && r.id && r.id_tipo_documento === TIPO_PDF).length;
const yaCompletas = filas.filter((f) => !f.cargo_xml && !f.cargo_pdf && f.motivos.has('ya_tenia_ambos'));
// Sin carga y sin explicacion inofensiva: son las que hay que revisar a mano.
const sinNada = filas.filter((f) => !f.cargo_xml && !f.cargo_pdf && !f.motivos.has('ya_tenia_ambos'));
const huerfanos = pares.filter((p) => !p.xml_file_id || !p.pdf_file_id);

const L = [];
L.push('================================================================');
L.push(' CARGA DE FACTURAS DE CONDENSADORAS -> tabla documentos');
L.push(' Ejecutado: ' + $now.toISO());
L.push('================================================================');
L.push(' Archivos en Drive .......... ' + totalArchivos);
L.push(' Facturas (folios) .......... ' + pares.length);
L.push(' Con cuenta de cobranza ..... ' + conCuenta + ' de ' + filas.length);
L.push(' Documentos insertados ...... ' + (insXml + insPdf) + '  (xml: ' + insXml + ' | pdf: ' + insPdf + ')');
L.push(' Ya tenian ambos docs ....... ' + yaCompletas.length);
L.push(' Facturas a revisar ......... ' + sinNada.length);
L.push('');
L.push('== RESUMEN (cuenta_cobranza,pdf,xml) ==');
L.push('cuenta_cobranza,pdf,xml');
for (const f of filas) {
  L.push((f.id_cuenta_cobranza || 'SIN_CUENTA') + ',' + si(f.cargo_pdf) + ',' + si(f.cargo_xml));
}
L.push('');
L.push('== DETALLE (CSV) ==');
L.push([
  'factura', 'uuid', 'proyecto', 'proyecto_inferido_por_modelo', 'modelo', 'num_depa',
  'numero_propiedad', 'id_propiedad', 'cuenta_cobranza', 'descripcion',
  'ya_tenia_pdf', 'ya_tenia_xml', 'cargo_pdf', 'cargo_xml', 'razon_no_carga',
  'archivo_pdf', 'archivo_xml', 'url_pdf', 'url_xml'
].join(','));
for (const f of filas) {
  L.push([
    csv(f.folio), csv(f.uuid), csv(f.proyecto), csv(si(f.inferido)), csv(f.modelo), csv(f.num_depa),
    csv(f.numero_propiedad), csv(f.id_propiedad), csv(f.id_cuenta_cobranza), csv(f.descripcion),
    csv(si(f.tenia_pdf)), csv(si(f.tenia_xml)), csv(si(f.cargo_pdf)), csv(si(f.cargo_xml)),
    csv([...f.motivos].map(explicar).join(' | ')),
    csv(f.pdf_name), csv(f.xml_name), csv(urlDe(f, 'pdf')), csv(urlDe(f, 'xml'))
  ].join(','));
}
if (sinNada.length) {
  L.push('');
  L.push('== FACTURAS A REVISAR (no se cargo nada) ==');
  for (const f of sinNada) {
    L.push('- ' + (f.folio || '?') +
      ' | proyecto: ' + (f.proyecto || '?') +
      ' | depa: ' + (f.num_depa || '?') +
      ' | cuenta: ' + (f.id_cuenta_cobranza || 'SIN_CUENTA') +
      ' | razon: ' + ([...f.motivos].map(explicar).join(' | ') || 'sin motivo registrado'));
    if (f.descripcion) L.push('    descripcion: ' + f.descripcion);
  }
}
if (huerfanos.length) {
  L.push('');
  L.push('== FOLIOS SIN PAR COMPLETO EN DRIVE ==');
  for (const h of huerfanos) {
    L.push('- ' + h.folio + ' | xml: ' + (h.xml_name || 'FALTA') + ' | pdf: ' + (h.pdf_name || 'FALTA'));
  }
}

return [{
  json: {
    log_txt: L.join('\n'),
    facturas: filas.length,
    con_cuenta: conCuenta,
    insertados: insXml + insPdf,
    insertados_xml: insXml,
    insertados_pdf: insPdf,
    a_revisar: sinNada.length,
    ya_completas: yaCompletas.length
  }
}];
